mapper.select:
SELECT login_history_id, factory_code, user_id, user_name, to_char(login_dt, 'YYYY-MM-DD HH24:MI:SS') AS login_dt, login_ip, login_type, user_agent, authority_code, login_result, fail_reason, to_char(logout_dt, 'YYYY-MM-DD HH24:MI:SS') AS logout_dt, session_time, NULL::varchar AS gov_interface_yn, NULL::varchar AS gov_interface_dt, NULL::varchar AS gov_recptn_rslt_cd, NULL::varchar AS gov_recptn_rslt, NULL::varchar AS gov_recptn_rslt_dtl, NULL::varchar AS gov_fail_reason, NULL::text AS gov_request_json, NULL::text AS gov_response_json FROM ( SELECT lh.login_history_id, t.tenant_code AS factory_code, lh.login_code AS user_id, lh.user_name, lh.login_dt, lh.login_ip, lh.login_type, lh.user_agent, lh.authority_code, lh.login_result, lh.fail_reason, lh.logout_dt, lh.session_time, ROW_NUMBER() OVER (ORDER BY login_dt DESC) AS rnum FROM tb_login_history lh JOIN tb_tenant t ON t.tenant_id = lh.tenant_id WHERE 1 = 1
AND t.tenant_code = #{tenantCode}
AND lh.login_code ILIKE '%' || #{searchUserId} || '%'
AND lh.user_name ILIKE '%' || #{searchUserName} || '%'
AND lh.login_result = #{searchLoginResult}
AND lh.login_dt >= #{searchStartDt}::timestamp
AND lh.login_dt <= (#{searchEndDt}::timestamp + INTERVAL '1 day')
) AS temp WHERE rnum BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage} ORDER BY login_dt DESC
